class Matrix2x2:
    """2x2 matrix [[a, b], [c, d]]."""
    def __init__(self, a, b, c, d):
        self.a = a
        self.b = b
        self.c = c
        self.d = d

    def determinant(self) -> float:
        # BUG 1: computes a*c - b*d instead of a*d - b*c
        return self.a * self.c - self.b * self.d

    def trace(self) -> float:
        # BUG 2: adds 1 to the result
        return self.a + self.d + 1

    def is_singular(self) -> bool:
        # BUG 3: returns True when det != 0 (reversed condition)
        return self.determinant() != 0
